#ifdef CK7
void test_device_ptr_addr(int arg) {
  int *p;
  #pragma omp target data use_device_ptr(p) use_device_addr(arg)
  { ++arg, ++(*p); }

  short x[10];
  short *xp = &x[0];

  x[1] = 111;

  #pragma omp target data map(tofrom: x) use_device_addr(xp[1:3])
  {
    xp[1] = 222;
  }
}
#endif
